<?php
declare(strict_types=1);

namespace MotorsportDB\API\Utils;

use MotorsportDB\API\Data\Database;

/**
 * Serves a JSON file generated by bin/build.php (var/). The browser downloads
 * it once, then revalidates it with its ETag on every use (304 while the data
 * is unchanged), so a rebuild is seen at once.
 */
final class BuildFile
{
    public static function serve(string $name): never
    {
        ini_set('display_errors', '0');
        $file = Database::varDir() . '/' . basename($name);
        if (!is_file($file)) {
            http_response_code(503);
            header('Content-Type: application/json');
            echo '{"error":"Data not built"}';
            exit;
        }

        $etag = '"' . hash('xxh128', filemtime($file) . ':' . filesize($file)) . '"';
        header('Content-Type: application/json; charset=UTF-8');
        header('X-Content-Type-Options: nosniff');
        header('Cache-Control: no-cache'); // revalidated on every use (304 while unchanged): a rebuild is seen at once
        header('ETag: ' . $etag);
        // mod_deflate appends "-gzip" to the ETag of compressed responses: compare the base value
        $sent = array_map(
            fn($t) => preg_replace('/^W\//', '', str_replace('-gzip"', '"', trim($t))),
            explode(',', $_SERVER['HTTP_IF_NONE_MATCH'] ?? '')
        );
        if (in_array($etag, $sent, true)) {
            http_response_code(304);
            exit;
        }
        header('Content-Length: ' . filesize($file));
        readfile($file);
        exit;
    }
}
